--liquibase formatted sql

--changeset quiz-bank:1
-- The quiz's material per word: its type (wrong options are always words of the same type), which stored
-- meanings are unfit as answers ('tr'/'en': wrong, untranslated or mixing senses), and exam-style gap items
-- built on the word's example sentences (Ekilex forms; every item checked to have exactly one right answer).
ALTER TABLE words ADD COLUMN IF NOT EXISTS pos TEXT;
ALTER TABLE words ADD COLUMN IF NOT EXISTS quiz_bad_meaning TEXT[] NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS word_quiz_items (
    id SERIAL PRIMARY KEY,
    word_id TEXT NOT NULL REFERENCES words(id) ON DELETE CASCADE,
    sentence_id INTEGER NOT NULL REFERENCES word_sentences(id) ON DELETE CASCADE,
    answer TEXT NOT NULL,          -- the word's form exactly as it appears in the sentence
    morph_code TEXT NOT NULL,      -- Ekilex code of that form (IndPrSg1, SgIll…), '-' for indeclinables
    form_options TEXT[] NOT NULL DEFAULT '{}', -- 3 other forms of the word that don't fit the gap
    word_options TEXT[] NOT NULL DEFAULT '{}', -- 3 other words in the same form that don't fit
    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    UNIQUE (sentence_id, answer)
);
CREATE INDEX IF NOT EXISTS idx_word_quiz_items_word ON word_quiz_items (word_id);

